function hiddenBaiduAds() {
    let ads = Array.from(document.querySelectorAll('.gp2k11k'));
    ads.forEach(d => d.id = 'hidden_ad')
}
function appendStyle() {
    let style = document.createElement('style')
    style.type = "text/css"
    style.innerText = `#hidden_ad {
        display: none !important;
        background: skyblue;
        height: 40px;
        overflow: auto;
    }`
    document.head.append(style)
}
if (!window.__removeBaiduAdsInit) {
    window.__removeBaiduAdsInit = true
    appendStyle()
    hiddenBaiduAds()
    setInterval(function () {
        // 每次都需要 appendStyle 才会生效
        appendStyle()
        hiddenBaiduAds()
    }, 1000)
    console.log('去除百度广告 init')
}
